use std::fs;
use std::path::{Path, PathBuf};
use std::env;

#[derive(Debug, Default)]
struct DesktopEntry {
    filename: String,
    name: String,
    exec: String,
    mimetypes: Vec<String>,
    no_display: bool,
}

fn parse_desktop_entry(path: &Path) -> Option<DesktopEntry> {
    let content = fs::read_to_string(path).ok()?;
    let mut entry = DesktopEntry::default();
    entry.filename = path.file_name()?.to_str()?.to_string();

    let mut current_section = "";
    for line in content.lines() {
        let line = line.trim();
        if line.starts_with('[') && line.ends_with(']') {
            current_section = &line[1..line.len()-1];
        } else if current_section == "Desktop Entry" {
            if let Some((key, value)) = line.split_once('=') {
                match key.trim() {
                    "Name" => entry.name = value.trim().to_string(),
                    "Exec" => entry.exec = value.trim().to_string(),
                    "MimeType" => {
                        entry.mimetypes = value.split(';')
                            .map(|s| s.trim().to_string())
                            .filter(|s| !s.is_empty())
                            .collect();
                    }
                    "NoDisplay" => entry.no_display = value.trim() == "true",
                    _ => {}
                }
            }
        }
    }
    Some(entry)
}

fn get_desktop_entries() -> Vec<DesktopEntry> {
    let mut entries = Vec::new();
    let mut paths = Vec::new();

    if let Ok(home) = env::var("HOME") {
        paths.push(PathBuf::from(home).join(".local/share/applications"));
    }

    if let Ok(data_dirs) = env::var("XDG_DATA_DIRS") {
        for dir in data_dirs.split(':') {
            paths.push(PathBuf::from(dir).join("applications"));
        }
    } else {
        paths.push(PathBuf::from("/usr/local/share/applications"));
        paths.push(PathBuf::from("/usr/share/applications"));
    }

    for path in paths {
        if let Ok(read_dir) = fs::read_dir(path) {
            for entry in read_dir.flatten() {
                if entry.path().extension().map_or(false, |ext| ext == "desktop") {
                    if let Some(desktop_entry) = parse_desktop_entry(&entry.path()) {
                        entries.push(desktop_entry);
                    }
                }
            }
        }
    }
    entries
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        // print help
        return;
    }

    match args[1].as_str() {
        "list" => {
            // TODO
        }
        _ => {}
    }
}
