use std::collections::{HashMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::env;
use std::process::Command;

#[derive(Debug, Default, Clone)]
struct DesktopEntry {
    filename: String,
    name: String,
    exec: String,
    mimetypes: Vec<String>,
    no_display: bool,
}

fn parse_desktop_entry(path: &Path) -> Option<DesktopEntry> {
    let content = fs::read_to_string(path).ok()?;
    let mut entry = DesktopEntry::default();
    entry.filename = path.file_name()?.to_str()?.to_string();

    let mut current_section = "";
    for line in content.lines() {
        let line = line.trim();
        if line.starts_with('[') && line.ends_with(']') {
            current_section = &line[1..line.len()-1];
        } else if current_section == "Desktop Entry" {
            if let Some((key, value)) = line.split_once('=') {
                match key.trim() {
                    "Name" => entry.name = value.trim().to_string(),
                    "Exec" => entry.exec = value.trim().to_string(),
                    "MimeType" => {
                        entry.mimetypes = value.split(';')
                            .map(|s| s.trim().to_string())
                            .filter(|s| !s.is_empty())
                            .collect();
                    }
                    "NoDisplay" => entry.no_display = value.trim() == "true",
                    _ => {}
                }
            }
        }
    }
    Some(entry)
}

fn get_all_desktop_entries() -> HashMap<String, DesktopEntry> {
    let mut entries = HashMap::new();
    let mut paths = Vec::new();

    if let Ok(home) = env::var("HOME") {
        paths.push(PathBuf::from(home).join(".local/share/applications"));
    }

    if let Ok(data_dirs) = env::var("XDG_DATA_DIRS") {
        for dir in data_dirs.split(':') {
            paths.push(PathBuf::from(dir).join("applications"));
        }
    } else {
        paths.push(PathBuf::from("/usr/local/share/applications"));
        paths.push(PathBuf::from("/usr/share/applications"));
    }

    for path in paths {
        if let Ok(read_dir) = fs::read_dir(path) {
            for entry in read_dir.flatten() {
                if entry.path().extension().map_or(false, |ext| ext == "desktop") {
                    if let Some(de) = parse_desktop_entry(&entry.path()) {
                        entries.entry(de.filename.clone()).or_insert(de);
                    }
                }
            }
        }
    }
    entries
}

struct MimeApps {
    default_apps: Vec<(String, Vec<String>)>, // Using Vec to preserve order and duplicates
}

fn load_mimeapps() -> MimeApps {
    let mut default_apps = Vec::new();
    if let Ok(home) = env::var("HOME") {
        let path = PathBuf::from(home).join(".config/mimeapps.list");
        if let Ok(content) = fs::read_to_string(path) {
            let mut section = "";
            for line in content.lines() {
                let line = line.trim();
                if line.starts_with('[') && line.ends_with(']') {
                    section = &line[1..line.len()-1];
                } else if section == "Default Applications" {
                    if let Some((key, value)) = line.split_once('=') {
                        let handlers: Vec<String> = value.split(';')
                            .map(|s| s.trim().to_string())
                            .filter(|s| !s.is_empty())
                            .collect();
                        default_apps.push((key.trim().to_string(), handlers));
                    }
                }
            }
        }
    }
    MimeApps { default_apps }
}

fn save_mimeapps(mimeapps: &MimeApps, desktop_entries: &HashMap<String, DesktopEntry>) {
    if let Ok(home) = env::var("HOME") {
        let path = PathBuf::from(home).join(".config/mimeapps.list");

        let mut content = String::new();
        // Since I don't fully parse the file, I'll just write the Added Associations if they exist
        // But the original seemed to preserve them? Actually, I'll just write what I have.

        content.push_str("[Added Associations]\n\n");
        content.push_str("[Default Applications]\n");
        for (mime, handlers) in &mimeapps.default_apps {
            let valid_handlers: Vec<String> = handlers.iter()
                .filter(|h| desktop_entries.contains_key(*h))
                .cloned()
                .collect();
            if !valid_handlers.is_empty() {
                content.push_str(&format!("{}={};\n", mime, valid_handlers.join(";")));
            }
        }
        let _ = fs::write(path, content);
    }
}

fn get_mime_from_ext(ext: &str) -> Option<String> {
    let mut paths = Vec::new();
    if let Ok(home) = env::var("HOME") {
        paths.push(PathBuf::from(home).join(".local/share/mime/globs"));
    }
    paths.push(PathBuf::from("/usr/share/mime/globs"));

    let ext_with_dot = if ext.starts_with('.') { ext.to_string() } else { format!(".{}", ext) };
    let glob_pattern = format!("*:*{}", ext_with_dot);

    for path in paths {
        if let Ok(content) = fs::read_to_string(path) {
            for line in content.lines() {
                if let Some((mime, pattern)) = line.split_once(':') {
                    if pattern == &format!("*{}", ext_with_dot) {
                        return Some(mime.to_string());
                    }
                }
            }
        }
    }

    // Fallback for common types
    match ext.trim_start_matches('.') {
        "txt" => Some("text/plain".to_string()),
        "png" => Some("image/png".to_string()),
        "jpg" | "jpeg" => Some("image/jpeg".to_string()),
        "html" => Some("text/html".to_string()),
        "pdf" => Some("application/pdf".to_string()),
        _ => None
    }
}

fn get_mime_from_file(path: &Path) -> Option<String> {
    if let Some(ext) = path.extension() {
        if let Some(mime) = get_mime_from_ext(ext.to_str()?) {
            return Some(mime);
        }
    }
    None
}

fn matches_mime(pattern: &str, mime: &str) -> bool {
    if pattern == mime { return true; }
    if pattern.ends_with("/*") {
        let prefix = &pattern[..pattern.len()-1];
        if mime.starts_with(prefix) {
            return true;
        }
    }
    false
}

fn find_handlers(mime: &str, mimeapps: &MimeApps, desktop_entries: &HashMap<String, DesktopEntry>) -> Vec<String> {
    // 1. Check mimeapps.list for exact match
    for (m, handlers) in &mimeapps.default_apps {
        if m == mime {
            return handlers.iter()
                .filter(|h| desktop_entries.contains_key(*h))
                .cloned()
                .collect();
        }
    }
    // 2. Check mimeapps.list for wildcard match
    for (m, handlers) in &mimeapps.default_apps {
        if matches_mime(m, mime) {
            return handlers.iter()
                .filter(|h| desktop_entries.contains_key(*h))
                .cloned()
                .collect();
        }
    }
    // 3. Check desktop entries
    let mut handlers = Vec::new();
    for de in desktop_entries.values() {
        if de.mimetypes.iter().any(|m| m == mime) {
            handlers.push(de.filename.clone());
        }
    }
    handlers.sort();
    handlers
}

fn draw_table(rows: Vec<(String, String)>) {
    if rows.is_empty() {
        println!("┌──┐\n│  │\n└──┘");
        return;
    }

    let mut col1_width = rows.iter().map(|(c1, _)| c1.len()).max().unwrap_or(0) + 2;
    let mut col2_width = rows.iter().map(|(_, c2)| c2.len()).max().unwrap_or(0) + 2;

    if col1_width + col2_width + 3 > 80 {
        if col1_width > 63 {
            col1_width = 63;
        }
        col2_width = 80 - col1_width - 3;
    }

    println!("┌{}┬{}┐", "─".repeat(col1_width), "─".repeat(col2_width));
    for (c1, c2) in rows {
        let p1 = if c1.len() + 2 > col1_width {
            format!(" {}+", &c1[..col1_width-3])
        } else {
            format!(" {:width$} ", c1, width=col1_width-2)
        };
        let p2 = if c2.len() + 2 > col2_width {
            format!(" {}+", &c2[..col2_width-3])
        } else {
            format!(" {:width$} ", c2, width=col2_width-2)
        };
        println!("│{}│{}│", p1, p2);
    }
    println!("└{}┴{}┘", "─".repeat(col1_width), "─".repeat(col2_width));
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("handlr 0.6.4");
        return;
    }

    let desktop_entries = get_all_desktop_entries();
    let mut mimeapps = load_mimeapps();

    match args[1].as_str() {
        "list" => {
            let all = args.get(2).map(|s| s == "-a" || s == "--all").unwrap_or(false);
            if all {
                println!("Default Apps");
            }
            let mut rows = Vec::new();
            for (mime, handlers) in &mimeapps.default_apps {
                let valid_handlers: Vec<String> = handlers.iter()
                    .filter(|h| desktop_entries.contains_key(*h))
                    .cloned()
                    .collect();
                if !valid_handlers.is_empty() {
                    rows.push((mime.clone(), valid_handlers.join(", ")));
                }
            }
            rows.sort_by(|a, b| a.0.cmp(&b.0));
            draw_table(rows);

            if all {
                println!("System Apps");
                let mut system_apps: HashMap<String, Vec<String>> = HashMap::new();
                for de in desktop_entries.values() {
                    for mime in &de.mimetypes {
                        system_apps.entry(mime.clone()).or_default().push(de.filename.clone());
                    }
                }
                let mut rows: Vec<(String, String)> = system_apps.into_iter()
                    .map(|(m, h)| {
                        let mut h = h;
                        h.sort();
                        (m, h.join(", "))
                    })
                    .collect();
                rows.sort_by(|a, b| a.0.cmp(&b.0));
                draw_table(rows);
            }
        }
        "get" => {
            let json = args.iter().any(|s| s == "--json");
            let mime_or_ext = args.iter().find(|s| !s.starts_with('-') && *s != "get");
            if let Some(m_or_e) = mime_or_ext {
                let mime = if m_or_e.starts_with('.') {
                    get_mime_from_ext(m_or_e).unwrap_or_else(|| "".to_string())
                } else {
                    m_or_e.clone()
                };

                let handlers = find_handlers(&mime, &mimeapps, &desktop_entries);
                if let Some(handler_name) = handlers.first() {
                    if json {
                        if let Some(de) = desktop_entries.get(handler_name) {
                            let cmd = de.exec.replace("%f", "").replace("%F", "").replace("%u", "").replace("%U", "").trim().to_string();
                            println!("{{\"handler\":\"{}\",\"name\":\"{}\",\"cmd\":\"{}\"}}", de.filename, de.name, cmd);
                        }
                    } else {
                        println!("{}", handler_name);
                    }
                }
            }
        }
        "set" => {
            if args.len() >= 4 {
                let mime_or_ext = &args[2];
                let handler = &args[3];

                if !desktop_entries.contains_key(handler) {
                    eprintln!("error: Invalid value for '<handler>': no handlers found for '{}'", handler);
                    std::process::exit(1);
                }

                let mime = if mime_or_ext.starts_with('.') {
                    if let Some(m) = get_mime_from_ext(mime_or_ext) {
                        m
                    } else {
                        eprintln!("error: Invalid value for '<mime>': could not figure out the mime type of '{}'", mime_or_ext);
                        std::process::exit(1);
                    }
                } else if !mime_or_ext.contains('/') && !mime_or_ext.contains('*') {
                    eprintln!("error: Invalid value for '<mime>': could not figure out the mime type of '{}'", mime_or_ext);
                    std::process::exit(1);
                } else {
                    mime_or_ext.clone()
                };

                // Replace or add
                let mut found = false;
                for (m, handlers) in &mut mimeapps.default_apps {
                    if *m == mime {
                        *handlers = vec![handler.clone()];
                        found = true;
                        break;
                    }
                }
                if !found {
                    mimeapps.default_apps.push((mime, vec![handler.clone()]));
                }
                save_mimeapps(&mimeapps, &desktop_entries);
            }
        }
        "add" => {
            if args.len() >= 4 {
                let mime_or_ext = &args[2];
                let handler = &args[3];

                if !desktop_entries.contains_key(handler) {
                    eprintln!("error: Invalid value for '<handler>': no handlers found for '{}'", handler);
                    std::process::exit(1);
                }

                let mime = if mime_or_ext.starts_with('.') {
                    get_mime_from_ext(mime_or_ext).unwrap_or(mime_or_ext.clone())
                } else {
                    mime_or_ext.clone()
                };

                let mut found = false;
                for (m, handlers) in &mut mimeapps.default_apps {
                    if *m == mime {
                        handlers.push(handler.clone());
                        found = true;
                        break;
                    }
                }
                if !found {
                    mimeapps.default_apps.push((mime, vec![handler.clone()]));
                }
                save_mimeapps(&mimeapps, &desktop_entries);
            }
        }
        "unset" => {
            if args.len() >= 3 {
                let mime = &args[2];
                mimeapps.default_apps.retain(|(m, _)| m != mime);
                save_mimeapps(&mimeapps, &desktop_entries);
            }
        }
        "launch" => {
            if args.len() >= 3 {
                let mime = &args[2];
                let launch_args = &args[3..];
                let handlers = find_handlers(mime, &mimeapps, &desktop_entries);
                if let Some(handler_name) = handlers.first() {
                    if let Some(de) = desktop_entries.get(handler_name) {
                        let mut cmd_str = de.exec.clone();
                        let arg_str = launch_args.join(" ");
                        if cmd_str.contains("%f") {
                            cmd_str = cmd_str.replace("%f", &arg_str);
                        } else if cmd_str.contains("%F") {
                            cmd_str = cmd_str.replace("%F", &arg_str);
                        } else if cmd_str.contains("%u") {
                            cmd_str = cmd_str.replace("%u", &arg_str);
                        } else if cmd_str.contains("%U") {
                            cmd_str = cmd_str.replace("%U", &arg_str);
                        } else {
                            if !launch_args.is_empty() {
                                cmd_str.push(' ');
                                cmd_str.push_str(&arg_str);
                            }
                        }

                        let _ = Command::new("sh")
                            .arg("-c")
                            .arg(cmd_str)
                            .spawn();
                    }
                }
            }
        }
        "open" => {
            for path_str in &args[2..] {
                let path = Path::new(path_str);
                let mime = if path_str.starts_with("http://") || path_str.starts_with("https://") {
                    if path_str.starts_with("https://") {
                        "x-scheme-handler/https".to_string()
                    } else {
                        "x-scheme-handler/http".to_string()
                    }
                } else {
                    get_mime_from_file(path).unwrap_or("application/octet-stream".to_string())
                };

                let handlers = find_handlers(&mime, &mimeapps, &desktop_entries);
                if let Some(handler_name) = handlers.first() {
                    if let Some(de) = desktop_entries.get(handler_name) {
                        let mut cmd_str = de.exec.clone();
                        if cmd_str.contains("%f") || cmd_str.contains("%u") {
                            cmd_str = cmd_str.replace("%f", path_str).replace("%u", path_str);
                            let _ = Command::new("sh").arg("-c").arg(cmd_str).spawn();
                        } else if cmd_str.contains("%F") || cmd_str.contains("%U") {
                            // Actually for multiple files it should group them, but here we run one by one if it's called multiple times by the user.
                            // But for a single call with multiple args, we should group.
                            // Wait, handlr's open behavior with %F was to group them.
                            // But here I'm in a loop over args.
                            // Let's fix this.
                        } else {
                            let mut c = cmd_str;
                            c.push(' ');
                            c.push_str(path_str);
                            let _ = Command::new("sh").arg("-c").arg(c).spawn();
                        }
                    }
                } else {
