    }
}

fn get_mime_from_ext(ext: &str) -> Option<String> {
    let mut paths = Vec::new();
    if let Ok(home) = env::var("HOME") {
        paths.push(PathBuf::from(home).join(".local/share/mime/globs"));
    }
    paths.push(PathBuf::from("/usr/share/mime/globs"));

    let ext_with_dot = if ext.starts_with('.') { ext.to_string() } else { format!(".{}", ext) };

    for path in paths {
        if let Ok(content) = fs::read_to_string(path) {
            for line in content.lines() {
                if let Some((mime, pattern)) = line.split_once(':') {
                    if pattern == &format!("*{}", ext_with_dot) {
                        return Some(mime.to_string());
                    }
                }
            }
        }
    }

    match ext.trim_start_matches('.') {
        "txt" => Some("text/plain".to_string()),
        "png" => Some("image/png".to_string()),
        "jpg" | "jpeg" => Some("image/jpeg".to_string()),
        "html" => Some("text/html".to_string()),
        "pdf" => Some("application/pdf".to_string()),
        _ => None
    }
}

fn get_mime_from_file(path: &Path) -> Option<String> {
    if let Some(ext) = path.extension() {
        if let Some(mime) = get_mime_from_ext(ext.to_str()?) {
            return Some(mime);
        }
    }
    None
}

fn matches_mime(pattern: &str, mime: &str) -> bool {
    if pattern == mime { return true; }
    if pattern.ends_with("/*") {
        let prefix = &pattern[..pattern.len()-1];
        if mime.starts_with(prefix) {
            return true;
        }
    }
    false
}

