        if m == mime {
            return handlers.iter().filter(|h| desktop_entries.contains_key(*h)).cloned().collect();
        }
    }
    for (m, handlers) in &mimeapps.default_apps {
        if matches_mime(m, mime) {
            return handlers.iter().filter(|h| desktop_entries.contains_key(*h)).cloned().collect();
        }
    }
    let mut handlers = Vec::new();
    for de in desktop_entries.values() {
        if de.mimetypes.iter().any(|m| m == mime) {
            handlers.push(de.filename.clone());
        }
    }
    handlers.sort();
    handlers
}

fn draw_table(rows: Vec<(String, String)>) {
    if rows.is_empty() {
        println!("┌──┐\n│  │\n└──┘");
        return;
    }

    let mut col1_width = rows.iter().map(|(c1, _)| c1.len()).max().unwrap_or(0) + 2;
    let mut col2_width = rows.iter().map(|(_, c2)| c2.len()).max().unwrap_or(0) + 2;

    if col1_width + col2_width + 3 > 80 {
        if col1_width > 63 {
            col1_width = 63;
        }
        col2_width = 80 - col1_width - 3;
    }

    println!("┌{}┬{}┐", "─".repeat(col1_width), "─".repeat(col2_width));
    for (c1, c2) in rows {
        let p1 = if c1.len() + 2 > col1_width {
            format!(" {}+", &c1[..col1_width-3])
        } else {
            format!(" {:width$} ", c1, width=col1_width-2)
        };
        let p2 = if c2.len() + 2 > col2_width {
            format!(" {}+", &c2[..col2_width-3])
        } else {
            format!(" {:width$} ", c2, width=col2_width-2)
        };
        println!("│{}│{}│", p1, p2);
    }
    println!("└{}┴{}┘", "─".repeat(col1_width), "─".repeat(col2_width));
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 || args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) {
        if args.len() > 1 && args[1] == "list" {
            println!("executable-list \nList default apps and the associated handlers\n\nUSAGE:\n    executable list [FLAGS]\n\nFLAGS:\n    -a, --all        \n    -h, --help       Prints help information\n    -V, --version    Prints version information");
        } else if args.len() > 1 && args[1] == "open" {
            println!("executable-open \nOpen a path/URL with its default handler\n\nUSAGE:\n    executable open <paths>...\n\nARGS:\n    <paths>...    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information");
        } else {
            println!("handlr 0.6.4\n\nUSAGE:\n    executable <SUBCOMMAND>\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nSUBCOMMANDS:\n    list      List default apps and the associated handlers\n    open      Open a path/URL with its default handler\n    set       Set the default handler for mime/extension\n    unset     Unset the default handler for mime/extension\n    launch    Launch the handler for specified extension/mime with optional arguments\n    get       Get handler for this mime/extension\n    add       Add a handler for given mime/extension Note that the first handler is the default");
        }
