            let all = args.contains(&"-a".to_string()) || args.contains(&"--all".to_string());
            if all { println!("Default Apps"); }
            let mut rows = Vec::new();
            for (mime, handlers) in &mimeapps.default_apps {
                let valid_handlers: Vec<String> = handlers.iter().filter(|h| desktop_entries.contains_key(*h)).cloned().collect();
                if !valid_handlers.is_empty() { rows.push((mime.clone(), valid_handlers.join(", "))); }
            }
            rows.sort_by(|a, b| a.0.cmp(&b.0));
            draw_table(rows);
            if all {
                println!("System Apps");
                let mut system_apps: HashMap<String, Vec<String>> = HashMap::new();
                for de in desktop_entries.values() {
                    for mime in &de.mimetypes { system_apps.entry(mime.clone()).or_default().push(de.filename.clone()); }
                }
                let mut rows: Vec<(String, String)> = system_apps.into_iter().map(|(m, h)| {
                    let mut h = h; h.sort(); (m, h.join(", "))
                }).collect();
                rows.sort_by(|a, b| a.0.cmp(&b.0));
                draw_table(rows);
            }
        }
        "get" => {
            let json = args.contains(&"--json".to_string());
            let m_or_e = args.iter().find(|s| !s.starts_with('-') && *s != "get").cloned().unwrap_or_default();
            let mime = if m_or_e.starts_with('.') { get_mime_from_ext(&m_or_e).unwrap_or_default() } else { m_or_e };
            let handlers = find_handlers(&mime, &mimeapps, &desktop_entries);
            if let Some(h_name) = handlers.first() {
                if json {
                    if let Some(de) = desktop_entries.get(h_name) {
                        let cmd = de.exec.replace("%f", "").replace("%F", "").replace("%u", "").replace("%U", "").trim().to_string();
                        println!("{{\"handler\":\"{}\",\"name\":\"{}\",\"cmd\":\"{}\"}}", de.filename, de.name, cmd);
                    }
                } else { println!("{}", h_name); }
            } else { eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})"); }
        }
        "set" => {
            if args.len() >= 4 {
                let m_or_e = &args[2];
                let handler = &args[3];
                if !desktop_entries.contains_key(handler) {
                    eprintln!("error: Invalid value for '<handler>': no handlers found for '{}'", handler);
                    std::process::exit(1);
                }
                let mime = if m_or_e.starts_with('.') {
                    get_mime_from_ext(m_or_e).unwrap_or_else(|| { eprintln!("error: Invalid value for '<mime>': could not figure out the mime type of '{}'", m_or_e); std::process::exit(1); })
                } else if !m_or_e.contains('/') && !m_or_e.contains('*') {
                    eprintln!("error: Invalid value for '<mime>': could not figure out the mime type of '{}'", m_or_e);
                    std::process::exit(1);
                } else { m_or_e.clone() };
                let mut found = false;
                for (m, hs) in &mut mimeapps.default_apps { if *m == mime { *hs = vec![handler.clone()]; found = true; break; } }
                if !found { mimeapps.default_apps.push((mime, vec![handler.clone()])); }
                save_mimeapps(&mimeapps, &desktop_entries);
            }
        }
        "add" => {
            if args.len() >= 4 {
                let m_or_e = &args[2];
                let handler = &args[3];
                if !desktop_entries.contains_key(handler) {
                    eprintln!("error: Invalid value for '<handler>': no handlers found for '{}'", handler);
                    std::process::exit(1);
                }
                let mime = if m_or_e.starts_with('.') { get_mime_from_ext(m_or_e).unwrap_or(m_or_e.clone()) } else { m_or_e.clone() };
                let mut found = false;
                for (m, hs) in &mut mimeapps.default_apps { if *m == mime { hs.push(handler.clone()); found = true; break; } }
                if !found { mimeapps.default_apps.push((mime, vec![handler.clone()])); }
                save_mimeapps(&mimeapps, &desktop_entries);
            }
        }
        "unset" => {
            if args.len() >= 3 {
                let mime = &args[2];
                mimeapps.default_apps.retain(|(m, _)| m != mime);
                save_mimeapps(&mimeapps, &desktop_entries);
            }
        }
        "launch" => {
            if args.len() >= 3 {
                let mime = &args[2];
                let launch_args = &args[3..];
                let handlers = find_handlers(mime, &mimeapps, &desktop_entries);
                if let Some(h_name) = handlers.first() {
                    if let Some(de) = desktop_entries.get(h_name) {
                        let mut cmd_str = de.exec.clone();
                        let arg_str = launch_args.join(" ");
                        if cmd_str.contains("%f") { cmd_str = cmd_str.replace("%f", &arg_str); }
                        else if cmd_str.contains("%F") { cmd_str = cmd_str.replace("%F", &arg_str); }
                        else if cmd_str.contains("%u") { cmd_str = cmd_str.replace("%u", &arg_str); }
                        else if cmd_str.contains("%U") { cmd_str = cmd_str.replace("%U", &arg_str); }
                        else if !launch_args.is_empty() { cmd_str.push(' '); cmd_str.push_str(&arg_str); }
                        let _ = Command::new("sh").arg("-c").arg(cmd_str).spawn();
                    }
                }
            }
        }
        "open" => {
            let mut groups: HashMap<String, Vec<String>> = HashMap::new();
            for p in &args[2..] {
                let mime = if p.contains("://") {
                    let scheme = p.split_once("://").map(|(s, _)| s).unwrap_or("");
                    format!("x-scheme-handler/{}", scheme)
                } else { get_mime_from_file(Path::new(p)).unwrap_or("application/octet-stream".to_string()) };
                if let Some(h) = find_handlers(&mime, &mimeapps, &desktop_entries).first() { groups.entry(h.clone()).or_default().push(p.clone()); }
                else { eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})"); }
            }
            for (h_name, ps) in groups {
                if let Some(de) = desktop_entries.get(&h_name) {
                    let cmd = de.exec.clone();
                    if cmd.contains("%F") || cmd.contains("%U") {
                        let _ = Command::new("sh").arg("-c").arg(cmd.replace("%F", &ps.join(" ")).replace("%U", &ps.join(" "))).spawn();
                    } else if cmd.contains("%f") || cmd.contains("%u") {
                        for p in ps { let _ = Command::new("sh").arg("-c").arg(cmd.replace("%f", &p).replace("%u", &p)).spawn(); }
                    } else {
                        for p in ps { let mut c = cmd.clone(); c.push(' '); c.push_str(&p); let _ = Command::new("sh").arg("-c").arg(c).spawn(); }
                    }
                }
            }
        }
        _ => {}
    }
}
