                if !v.is_empty() { rows.push((m.clone(), v.join(", "))); }
            }
            rows.sort(); draw_table(rows);
            if all {
                println!("System Apps");
                let mut system: HashMap<String, Vec<String>> = HashMap::new();
                for de in desktop_entries.values() { for m in &de.mimetypes { system.entry(m.clone()).or_default().push(de.filename.clone()); } }
                let mut rows: Vec<(String, String)> = system.into_iter().map(|(m, mut h)| { h.sort(); (m, h.join(", ")) }).collect();
                rows.sort(); draw_table(rows);
            }
        }
        "get" => {
            let json = args.contains(&"--json".to_string());
            let m_or_e = args.iter().find(|s| !s.starts_with('-') && *s != "get").cloned().unwrap_or_default();
            let mime = if m_or_e.starts_with('.') { get_mime_from_ext(&m_or_e).unwrap_or_default() } else { m_or_e };
            let hs = find_handlers(&mime, &mimeapps, &desktop_entries);
            if let Some(h) = hs.first() {
                if json { let de = &desktop_entries[h]; let cmd = de.exec.replace("%f","").replace("%F","").replace("%u","").replace("%U","").trim().to_string(); println!("{{\"handler\":\"{}\",\"name\":\"{}\",\"cmd\":\"{}\"}}", de.filename, de.name, cmd); }
                else { println!("{}", h); }
            } else { eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})"); }
        }
        "set" => {
            if args.len() < 4 { return; }
            let m_or_e = &args[2]; let h = &args[3];
            if !desktop_entries.contains_key(h) { eprintln!("error: Invalid value for '<handler>': no handlers found for '{}'", h); std::process::exit(1); }
            let mime = if m_or_e.starts_with('.') { get_mime_from_ext(m_or_e).unwrap_or_else(|| { eprintln!("error: Invalid value for '<mime>': could not figure out the mime type of '{}'", m_or_e); std::process::exit(1); }) }
                       else if !m_or_e.contains('/') && !m_or_e.contains('*') { eprintln!("error: Invalid value for '<mime>': could not figure out the mime type of '{}'", m_or_e); std::process::exit(1); }
                       else { m_or_e.clone() };
            let mut found = false;
            for (m, hs) in &mut mimeapps.default_apps { if *m == mime { *hs = vec![h.clone()]; found = true; break; } }
            if !found { mimeapps.default_apps.push((mime, vec![h.clone()])); }
            save_mimeapps(&mimeapps, &desktop_entries);
        }
        "add" => {
            if args.len() < 4 { return; }
            let m_or_e = &args[2]; let h = &args[3];
            if !desktop_entries.contains_key(h) { eprintln!("error: Invalid value for '<handler>': no handlers found for '{}'", h); std::process::exit(1); }
            let mime = if m_or_e.starts_with('.') { get_mime_from_ext(m_or_e).unwrap_or(m_or_e.clone()) } else { m_or_e.clone() };
            let mut found = false;
            for (m, hs) in &mut mimeapps.default_apps { if *m == mime { hs.push(h.clone()); found = true; break; } }
            if !found { mimeapps.default_apps.push((mime, vec![h.clone()])); }
            save_mimeapps(&mimeapps, &desktop_entries);
        }
        "unset" => { if args.len() >= 3 { let mime = &args[2]; mimeapps.default_apps.retain(|(m, _)| m != mime); save_mimeapps(&mimeapps, &desktop_entries); } }
        "launch" => {
            if args.len() >= 3 {
                let mime = &args[2]; let la = &args[3..];
                let hs = find_handlers(mime, &mimeapps, &desktop_entries);
                if let Some(h) = hs.first() {
                    let de = &desktop_entries[h]; let mut c = de.exec.clone(); let as_ = la.join(" ");
                    if c.contains("%f") { c = c.replace("%f", &as_); } else if c.contains("%F") { c = c.replace("%F", &as_); }
                    else if c.contains("%u") { c = c.replace("%u", &as_); } else if c.contains("%U") { c = c.replace("%U", &as_); }
                    else if !la.is_empty() { c.push(' '); c.push_str(&as_); }
                    let _ = Command::new("sh").arg("-c").arg(c).spawn();
                }
            }
        }
        "open" => {
            let mut groups: HashMap<String, Vec<String>> = HashMap::new();
            for p in &args[2..] {
                let m = if p.contains("://") { let s = p.split_once("://").map(|(s, _)| s).unwrap_or(""); format!("x-scheme-handler/{}", s) }
                        else { get_mime_from_file(Path::new(p)).unwrap_or("application/octet-stream".to_string()) };
                if let Some(h) = find_handlers(&m, &mimeapps, &desktop_entries).first() { groups.entry(h.clone()).or_default().push(p.clone()); }
                else { eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})"); }
            }
            for (h, ps) in groups {
                let de = &desktop_entries[&h]; let c = de.exec.clone();
                if c.contains("%F") || c.contains("%U") { let _ = Command::new("sh").arg("-c").arg(c.replace("%F", &ps.join(" ")).replace("%U", &ps.join(" "))).spawn(); }
                else if c.contains("%f") || c.contains("%u") { for p in ps { let _ = Command::new("sh").arg("-c").arg(c.replace("%f", &p).replace("%u", &p)).spawn(); } }
                else { for p in ps { let mut c_ = c.clone(); c_.push(' '); c_.push_str(&p); let _ = Command::new("sh").arg("-c").arg(c_).spawn(); } }
            }
        }
        _ => {}
    }
}
